import { WhatAuthSDK } from '@whatauth/sdk';

const whatAuth = new WhatAuthSDK({
  apiKey: 'tu-api-key-aqui',
  environment: 'development'
});

async function authenticateUser(email, password) {
  try {
    const result = await whatAuth.authenticate({
      email,
      password
    });

    if (result.success) {
      localStorage.setItem('token', result.token);
      return result.user;
    }
  } catch (error) {
    console.error('Error de autenticación:', error);
  }
}

// Test de integración
const testAuth = async () => {
  const testUser = await authenticateUser(
    'test@example.com',
    'password123'
  );

  console.log('Usuario autenticado:', testUser);
};

testAuth();

